package br.com.weg.workshop.post.domain; import br.com.weg.workshop.user.domain.UserEntity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="post_comment",schema="workshop") public class PostComment { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="post_id",nullable=false) private Post post; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private UserEntity user; @Column(nullable=false,columnDefinition="TEXT") private String content; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; protected PostComment(){} public static PostComment create(Post p,UserEntity u,String c){PostComment x=new PostComment();x.id=UUID.randomUUID();x.post=p;x.user=u;x.content=c;x.createdAt=Instant.now();x.updatedAt=x.createdAt;return x;} public UUID getId(){return id;} public Post getPost(){return post;} public UserEntity getUser(){return user;} public String getContent(){return content;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} }
